    "لا تستخدم إذا انتهت صلاحية المنتج أو أظهر الشريط علامات العبث.",
    "إذا كنت تتناول أدوية تؤثر على المزاج أو الأعصاب أو نظم القلب، فيجب استشارة أخصائي طبي.",
